 const labels={'work.saved':["Work version saved","Completed"],'work.completed':["Isolated JavaScript work","Completed"],'work.failed':["Isolated JavaScript work","Incomplete"],'work.cancelled':["Isolated JavaScript work","Cancelled"],'work.timed_out':["Isolated JavaScript work","Stopped"],'work.interrupted':["Isolated JavaScript work","Interrupted by restart"],'document.read':["Document reading","Completed"],'memory.searched':["Own memory search","Completed"],'record.read':["Original record reading","Completed"],'tool.note.result':["Controlled notes","Completed"],'consult.result':["Independent model consultation","Completed"],'consult.failed':["Independent model consultation","Incomplete"],'tool.owner_reply':["Reply to Owner","Completed"],'tool.owner_message':["Proactive message to Owner","Saved; not necessarily read"],'tool.web.result':["Web work","Result reported"],'tool.web.failed':["Web work","Incomplete"],'tool.denied':["Tool use","Denied"],'cycle.committed':["Model activity","Completed"],'cycle.incomplete':["Model activity","Completion unconfirmed"]};
