 const heading=el('h3',"Memory usage and versions"),notice=el('p',"Read-only: does not modify memory or start activity."),usage=el('p'),refresh=el('button',"Refresh memory and versions"),message=el('p'),current=el('details'),history=el('details'),select=el('select'),read=el('button',"Read selected version and differences"),more=el('button',"Load earlier versions"),detail=el('div');
 refresh.id='memoryRefresh';usage.id='memoryUsage';message.id='memoryMessage';message.setAttribute('role','status');current.id='memoryCurrent';history.id='memoryHistory';select.id='memoryVersionSelect';read.id='memoryReadVersion';more.id='memoryMore';detail.id='memoryVersionDetail';
 current.append(el('summary',"View loaded cumulative memory, plans and summary"));
