 const home=el('section');home.id='ownerWelcomeGuide';home.append(el('h3',"First use: follow this sequence"),el('p',"Platform setup → Create individual → Write and save draft → Preview and approve → Life settings → Personally confirm birth → Read activity and outputs"));const read=el('button',"Read the full user guide");read.onclick=()=>navigate('help');home.append(read);pageMap.home.prepend(home);
