 function paint(){const e=current(),g=ownerGuide(e,status,{settings:ui.hasUnsavedSettings,permissions:ui.hasUnsavedPermissions});action=g.destination;title.textContent=g.title;next.textContent=g.next;next.disabled=busy||ui.pending;body.textContent="Progress reflects saved data. Viewing, switching, and Next never approve, cause birth, or start life on your behalf.";if(e?.life.state==='unborn'&&birthCheck?.individual_id===ui.scope)body.textContent+=" Based on saved settings, first activity: "+firstActivityLabel(birthCheck.next_window_start,Date.now(),status.timezone)+"; latest end: "+firstActivityLabel(birthCheck.first_window.end,Date.now(),status.timezone)+'。';for(const [key,{footer,p,b}]of Object.entries(footers)){footer.hidden=!e||e.life.state!=='unborn';const dirty=key==='settings'?ui.hasUnsavedSettings:ui.hasUnsavedPermissions;p.textContent=(e?.name??'')+'｜'+(dirty?"There are unsaved changes; save first.":"This page shows saved settings; you may continue.");b.disabled=busy||ui.pending;}}
